const CLOUD_KEYS=['izdelie-production-catalog-v1',LIB_KEY,QUOTES_KEY,COMPANY_KEY,STOCK_KEY,VARIANT_KEY,LINK_KEY,PROJECTS_KEY,OP_RATES_KEY,RateRepository.LEGACY_KEY,'izdelie-offcuts-v1','izdelie-working-drafts-v1','izdelie-price-review-v1','izdelie-fill-templates-v1'];
let cloudBase={},cloudVersions={};
function upgradeRemoteRates(data){if(!(OP_RATES_KEY in data)&&data[RateRepository.LEGACY_KEY]){const legacy=JSON.parse(data[RateRepository.LEGACY_KEY]),repo=RateRepository.create({read:(k,f)=>k===RateRepository.LEGACY_KEY?legacy:f,write:()=>false,seed:OPERATION_RATE_SEED});data[OP_RATES_KEY]=JSON.stringify(repo.materialize())}}
let cloudRevision=0,cloudReady=false,cloudBusy=false,cloudDirty=0,cloudTimer=null,cloudConflict=null,cloudStatus='Проверка подключения',cloudLastSaved='';
function cloudDataset(){const rates=rateRepository().materialize();if(!localWriteJSON(OP_RATES_KEY,rates))throw Error('Не удалось сохранить справочник ставок');return Object.fromEntries(CLOUD_KEYS.filter(k=>localStorage.getItem(k)!==null).map(k=>[k,localStorage.getItem(k)]))}
function datasetEmpty(d){return Object.values(d).every(v=>{try{const x=JSON.parse(v);return Array.isArray(x)?!x.length:x&&typeof x==='object'?!Object.keys(x).length:!x}catch{return false}})}
function cloudMessage(s){cloudStatus=s;const n=$('cloudNav');window.cloudIndicator=s;if(n)n.textContent='☁ Сервер и копии · '+s;if(page===17)refreshCloudPanel()}
const localWriteJSON=writeJSON;
writeJSON=function(k,v){const ok=localWriteJSON(k,v);if(ok&&CLOUD_KEYS.includes(k)){cloudDirty++;if(cloudReady&&!cloudConflict)scheduleCloud()}return ok};
function scheduleCloud(){clearTimeout(cloudTimer);cloudTimer=setTimeout(()=>syncCloud(),900);cloudMessage('Ожидает синхронизации')}
async function cloudRequest(path,options={}){const response=await fetch(path,{credentials:'same-origin',cache:'no-store',...options});const body=await response.json().catch(()=>({error:'Сервер вернул неожиданный ответ'}));if(!response.ok){const e=Error(body.error||'Сервер недоступен');e.status=response.status;throw e}return body}
async function connectCloud(){if(location.protocol==='file:'){cloudMessage('Автономный режим');return}try{const remote=await cloudRequest('/api/records');cloudBase=structuredClone(remote.data);upgradeRemoteRates(remote.data);cloudVersions={...remote.versions};cloudRevision=remote.revision;const localWasEmpty=datasetEmpty(Object.fromEntries(CLOUD_KEYS.filter(k=>localStorage.getItem(k)!==null).map(k=>[k,localStorage.getItem(k)]))),local=cloudDataset();if(datasetEmpty(remote.data)){cloudReady=true;cloudMessage('Сервер подключён');if(!datasetEmpty(local))await syncCloud();return}if(localWasEmpty||datasetEmpty(local)||documentFingerprint(local)===documentFingerprint(remote.data)){if(!installCloudData(remote.data))return;cloudReady=true;cloudDirty=0;cloudLastSaved=remote.updatedAt||'';cloudMessage('Синхронизировано');if(RecordProtocol.diff(cloudBase,cloudDataset(),cloudVersions).length){cloudDirty++;scheduleCloud()}return}remote.originalData=structuredClone(cloudBase);cloudConflict=remote;cloudReady=true;cloudMessage('Нужно объединить базы')}catch(e){cloudReady=false;cloudMessage(e.status===401||e.status===403?'Нужен вход на сайт':'Локально · сервер недоступен')}}
async function syncCloud(){if(!cloudReady||cloudBusy||cloudConflict)return;cloudBusy=true;const generation=cloudDirty,data=cloudDataset();cloudMessage('Сохранение на сервер');try{DomainSchema.dataset(data);const changes=RecordProtocol.diff(cloudBase,data,cloudVersions);for(let offset=0;offset<changes.length;offset+=25){const batch=changes.slice(offset,offset+25),result=await cloudRequest('/api/records',{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify({changes:batch})});cloudRevision=result.revision;Object.assign(cloudVersions,result.versions);cloudLastSaved=result.updatedAt;const flat=RecordProtocol.flatten(cloudBase);for(const r of batch)flat[RecordProtocol.key(r.collection,r.id)]=r;cloudBase=RecordProtocol.expand(Object.values(flat))}cloudDirty=Math.max(0,cloudDirty-generation);cloudMessage('Синхронизировано')}catch(e){if(e.status===409){cloudConflict=await cloudRequest('/api/records').catch(()=>null);cloudMessage('Конфликт записей · открыть сервер')}else cloudMessage('Локально · '+e.message)}finally{cloudBusy=false;if(cloudDirty&&!cloudConflict&&cloudStatus==='Синхронизировано')scheduleCloud()}}
function installCloudData(data){try{DomainSchema.dataset(data)}catch(e){cloudMessage('База не применена: '+e.message);return false}const old=Object.fromEntries(CLOUD_KEYS.map(k=>[k,localStorage.getItem(k)]));if(!localWriteJSON('izdelie-cloud-recovery-v4',{date:stamp(),data:Object.fromEntries(Object.entries(old).filter(([,v])=>v!==null))})){cloudMessage('Сначала скачайте локальную копию');return false}try{for(const k of CLOUD_KEYS)if(k in data)localStorage.setItem(k,data[k]);applyPreferredSources();return true}catch{for(const [k,v] of Object.entries(old))try{if(v===null)localStorage.removeItem(k);else localStorage.setItem(k,v)}catch{}cloudMessage('Не удалось загрузить базу; локальная копия сохранена');return false}}
function mergedCloudData(local,remote){const out={...local,...remote},parse=(d,k,f)=>{try{return JSON.parse(d[k]||'null')??f}catch{return f}};
 const localLib=parse(local,LIB_KEY,[]),remoteLib=parse(remote,LIB_KEY,[]),entries=new Map();for(const e of [...remoteLib,...localLib]){if(!e||!Array.isArray(e.revisions))continue;const prev=entries.get(e.id);if(!prev){entries.set(e.id,structuredClone(e));continue}const versions=new Map(prev.revisions.map(r=>[r.id,r]));for(const v of e.revisions)if(!versions.has(v.id))versions.set(v.id,v);prev.revisions=[...versions.values()].sort((a,b)=>String(a.date).localeCompare(String(b.date)));const last=prev.revisions.at(-1);prev.name=last.calculation.name;prev.code=last.calculation.code;prev.type=last.calculation.type;prev.updatedAt=last.date;}out[LIB_KEY]=JSON.stringify([...entries.values()]);
 for(const key of [QUOTES_KEY,VARIANT_KEY]){const m=new Map();for(const item of [...parse(remote,key,[]),...parse(local,key,[])]){const prior=m.get(item.id);if(!prior){m.set(item.id,structuredClone(item));continue}if(key===QUOTES_KEY&&documentFingerprint(prior.document)!==documentFingerprint(item.document)){const clone=structuredClone(item);clone.id=uid();m.set(clone.id,clone)}else if((item.updatedAt||item.date||item.createdAt||'')>(prior.updatedAt||prior.date||prior.createdAt||''))m.set(item.id,structuredClone(item));}out[key]=JSON.stringify([...m.values()]);}
 for(const key of [STOCK_KEY,LINK_KEY,PROJECTS_KEY,'izdelie-offcuts-v1'])out[key]=JSON.stringify({...parse(local,key,{}),...parse(remote,key,{})});const draftKey='izdelie-working-drafts-v1',draftMap={...parse(remote,draftKey,{})};for(const [id,v] of Object.entries(parse(local,draftKey,{})))if(!draftMap[id]||v.updatedAt>draftMap[id].updatedAt)draftMap[id]=v;out[draftKey]=JSON.stringify(draftMap);out[OP_RATES_KEY]=JSON.stringify(RateRepository.merge(parse(local,OP_RATES_KEY,{}),parse(remote,OP_RATES_KEY,{})));const productionKey='izdelie-production-catalog-v1';if(local[productionKey]||remote[productionKey])out[productionKey]=JSON.stringify(ProductionModelCore.mergeDefinitions(parse(local,productionKey,{}),parse(remote,productionKey,{}),uid));const templateKey='izdelie-fill-templates-v1';if(local[templateKey]||remote[templateKey])out[templateKey]=JSON.stringify(ModelSpecCore.mergeTemplates(parse(local,templateKey,{}),parse(remote,templateKey,{}),uid));return out;}
async function resolveCloud(){if(!cloudConflict)return;const remoteData=structuredClone(cloudConflict.data);upgradeRemoteRates(remoteData);const merged=mergedCloudData(cloudDataset(),remoteData);if(!installCloudData(merged))return;cloudRevision=cloudConflict.revision;cloudVersions={...cloudConflict.versions};cloudBase=structuredClone(cloudConflict.originalData||cloudConflict.data);cloudConflict=null;cloudDirty++;await syncCloud();renderCloud()}
function downloadCloudRecovery(){const x=readJSON('izdelie-cloud-recovery-v4',null);download('local-base-before-sync-'+today()+'.json',JSON.stringify(x||{date:stamp(),data:cloudDataset()},null,2),'application/json')}
function renderCloud(){$('app').innerHTML=title('Данные / Хранение','Сервер и резервные копии','База изделий, КП, варианты, источники цен и остатки синхронизируются между устройствами.','Приватный доступ')+`<div class="card"><div id="cloudPanel"></div></div><div class="card"><div class="cardhead"><h2>Серверные резервные копии</h2><button onclick="loadCloudBackups()">Загрузить список</button></div><p class="small">Перед первым изменением базы за день сервер сохраняет предыдущую версию. Выданные КП входят в копию. Резервные копии не удаляются автоматически.</p><div id="cloudBackups"></div></div><div class="card"><h2>Локальное восстановление</h2><p class="small">Перед объединением сохраняется локальная копия. Рабочая калькуляция и черновик КП остаются на своём устройстве; сервер хранит сохранённые записи.</p><div class="mini-actions"><button onclick="downloadFullBackup()">Скачать всю локальную базу</button><button onclick="downloadCloudRecovery()">Копия перед синхронизацией</button><button onclick="fullBackupImportDialog()">Восстановить из файла</button></div></div>`;refreshCloudPanel()}
function refreshCloudPanel(){if(!$('cloudPanel'))return;$('cloudPanel').innerHTML=`<h2>${esc(cloudStatus)}</h2><p class="small">Серверная версия: ${cloudRevision}${cloudLastSaved?' · сохранено '+esc(new Date(cloudLastSaved).toLocaleString('ru-RU')):''}</p>${cloudConflict?'<div class="note">На устройстве и сервере есть разные данные. При объединении версии изделий сохраняются, различные выданные КП сохраняются отдельными записями. Для совпадающих ключей остатков, предпочтительных источников и реквизитов используются серверные значения. Различающиеся внутренние ставки сохраняются обе: локальная получает отметку конфликта. Локальная копия будет сохранена для восстановления.</div><div class="mini-actions"><button class="primary" onclick="resolveCloud()">Объединить и синхронизировать</button><button onclick="downloadFullBackup()">Скачать местную копию</button></div>':`<div class="mini-actions"><button onclick="${cloudReady?'syncCloud()':'connectCloud()'}">${cloudReady?'Синхронизировать сейчас':'Повторить подключение'}</button></div>`}<p class="small">При отсутствии сети изменения остаются локально. При ошибке или конфликте приложение не заявляет об успешном сохранении на сервере.</p>`}
async function loadCloudBackups(){try{const x=await cloudRequest('/api/backups');$('cloudBackups').innerHTML=x.backups.length?x.backups.map(b=>`<div class="version-row"><div>${esc(b.backup_day)}<span class="source">Версия ${b.rev} · ${esc(b.updated_at)}</span></div><button onclick="downloadServerBackup(${b.rev})">Скачать копию</button></div>`).join(''):'<p class="small">Копии появятся после первого изменения сохранённой базы.</p>'}catch(e){$('cloudBackups').textContent=e.message}}
async function downloadServerBackup(rev){try{const x=await cloudRequest('/api/backups/'+rev);download('server-base-v'+rev+'.json',JSON.stringify({format:'izdelie-full-backup',version:4,date:x.updatedAt,data:x.data},null,2),'application/json')}catch(e){toast(e.message)}}
function downloadFullBackup(){download('izdelie-all-'+today()+'.json',JSON.stringify({format:'izdelie-full-backup',version:4,date:stamp(),data:cloudDataset()},null,2),'application/json')}
function fullBackupImportDialog(){modal('Восстановить полную базу',`<p class="small">Данные файла объединятся с локальными. Предыдущая локальная копия сохранится. При подключённом сервере результат пройдёт проверку версии.</p><input type="file" accept=".json" onchange="restoreFullBackup(event)">`)}
async function restoreFullBackup(e){try{const f=e.target.files[0];if(!f||f.size>5000000)throw Error('Неподходящий размер файла');const x=JSON.parse(await f.text());if(x.format!=='izdelie-full-backup'||x.version!==4||!x.data||Object.entries(x.data).some(([k,v])=>!CLOUD_KEYS.includes(k)||typeof v!=='string'))throw Error('Требуется полный архив версии 4');for(const v of Object.values(x.data))JSON.parse(v);upgradeRemoteRates(x.data);if(!installCloudData(mergedCloudData(cloudDataset(),x.data)))return;cloudDirty++;if(cloudReady&&!cloudConflict)scheduleCloud();$('modal').close();go(17);toast('База восстановлена из копии')}catch(e){toast('Файл не применён: '+e.message)}}
connectCloud();
